## directly, only this pre-resolved value (Rule IX.1).
## hero_bonus_tier values (identical semantics to HeroAutoAttackEvent):
##   0 = STANDARD, 1 = ELITE, 2 = BOSS

@export var skill_id: StringName = &""
@export var target_id: int = -1
@export var skill_power: float = 0.0
@export var skill_power_coefficient: float = 0.0
@export var is_crit: bool = false
@export var crit_multiplier_effective: float = 1.0
@export var hero_bonus_tier: int = 0  ## 0 = STANDARD, 1 = ELITE, 2 = BOSS
## Hero Combat & Stats Redesign (2026-09-18): the cast skill's own damage_type
## (SkillDefinitionResource.effect_data.damage_type, "" normalized to
## "physical" by Hero at emission time -- see hero.gd's
## _resolve_skill_hit()). Drives D&S's mitigation branch: "physical" ->
## target_armor's curve, any other value -> target_elemental_resist, "true"
## -> no mitigation.
@export var damage_type: String = "physical"
## Target's MonsterResource.armor, resolved by Hero at emission time. Only
## consulted when damage_type == "physical".
@export var target_armor: float = 0.0
## Target's MonsterResource.evasion [0,100], resolved by Hero at emission
## time. Rolled first, before any damage math (Section 3.5.1).

## introducing one just for crit would be disproportionate scope.
@export var crit_chance: float = 0.0        # [0.0, 0.8]
## Flat multiplier applied to a hit's damage when crit_chance rolls true.
## No base-plus-bonus split (unlike Hero's CRIT_MULTIPLIER_BASE) — see
## crit_chance's own doc comment for why.
@export var crit_multiplier: float = 1.5    # [1.0, 3.0]
## Fraction of armored-monster damage mitigation (ARMORED_MITIGATION_
## MULTIPLIER in damage_status.gd, currently a flat 50%) this weapon negates.
## 0.0 = no change to today's mitigation; 1.0 = mitigation fully countered.
@export var armor_penetration: float = 0.0  # [0.0, 1.0]
## Chance per attack that this weapon's Power effect (PowerComponent.
## effect_type) actually applies. Previously effects always applied on every
## hit (no roll existed) — 1.0 preserves that behavior for existing content;
## values below 1.0 make status-effect towers a real probabilistic choice
## rather than a guarantee.
@export var status_proc_chance: float = 1.0 # [0.0, 1.0]
@export var damaged: bool = false

## D3 formula: floor(absorbed × fraction). Synchronous — ADR-0007 Level-1 cascade exemption.
func _on_monster_hp_absorbed(entity_id: int, absorbed: int) -> void:
	if not _lifesteal_pending.has(entity_id):
		return
	var fraction: float = _lifesteal_pending[entity_id]
	_lifesteal_pending.erase(entity_id)
	var heal_amount: int = floori(absorbed * fraction)
	if heal_amount > 0:
		GEventBus.hero_healed.emit(heal_amount)
